import{_ as a,o as r,c as o,a0 as t}from"./chunks/framework.B9sLprCo.js";const u=JSON.parse('{"title":"使用 Web UI","description":"","frontmatter":{"editSource":"docs/user/guide/index.md"},"headers":[],"relativePath":"guide/quickstart.md","filePath":"guide/quickstart.md"}'),s={name:"guide/quickstart.md"};function i(d,e,n,l,p,c){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="使用-web-ui" tabindex="-1">使用 Web UI <a class="header-anchor" href="#使用-web-ui" aria-label="Permalink to &quot;使用 Web UI&quot;">​</a></h1><p>请先按照<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/README.md#run" target="_blank" rel="noreferrer">根目录 README</a> 中的说明启动 Web UI；命令会打印其访问地址。本指南从服务器已经运行的状态开始。<code>dsh</code> 进程会把启动时所在的目录作为默认文件系统位置；全新的 Web UI 不会选中任何 Workspace。</p><h2 id="配置模型" tabindex="-1">配置模型 <a class="header-anchor" href="#配置模型" aria-label="Permalink to &quot;配置模型&quot;">​</a></h2><p>打开<strong>设置 → 模型</strong>，输入 <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek API 密钥</a>并保存。模型路由会立即可用，不需要重启服务器。</p><p><a href="./providers">模型配置指南</a>介绍其他提供方和自定义 OpenAI 兼容端点。</p><h2 id="选择开始方式" tabindex="-1">选择开始方式 <a class="header-anchor" href="#选择开始方式" aria-label="Permalink to &quot;选择开始方式&quot;">​</a></h2><p>点击<strong>选择工作区</strong>即可搜索已列出的 Workspace。若要在本地项目中工作，可选择已有 Workspace，或选择<strong>打开文件夹</strong>并选取项目目录。Session 打开后，编辑器即可使用。</p><p>选择<strong>不在项目中工作</strong>会在 Host 默认工作目录创建 Session，但不会注册 Workspace。只有没有当前 Session 时，编辑器才不可用。</p><p>在 Coding 桌面端中，选择<strong>连接 Remote-SSH</strong>，即可输入 SSH 主机、使用密码或私钥认证、确认未知主机密钥并选择远程目录。凭据只保留在当前对话框／连接中，不会保存；应用重启后需要重新执行连接流程。普通浏览器界面不能发起 SSH 连接。</p><p>Remote-SSH 会通过紧凑的 Go agent 在所选目录中运行语义文件系统操作、<code>glob</code>／<code>grep</code>、前台和后台 Bash、持久终端／PTY、LSP 与 Code Mode。目标侧不需要 Node；本地 Host 仍负责工具审批和持久 Session 日志。在拥有同执行世界的远程沙箱 Provider 出现前，远程 Bash 需要使用<strong>完全访问</strong>（<code>danger-full-access</code>）。Code Mode 会经 esbuild 转换 TypeScript，并在 Goja 中运行，因此它拥有声明的工具 binding，但没有 Node 内建模块、<code>process</code>、<code>require</code> 或 Host 环境。过期 marker 或已断开的连接会失败，而不会在本机运行操作。</p><h2 id="运行任务" tabindex="-1">运行任务 <a class="header-anchor" href="#运行任务" aria-label="Permalink to &quot;运行任务&quot;">​</a></h2><p>启动一个会话并发送：</p><blockquote><p>Summarize this repository and identify its main packages.</p></blockquote><p>Agent（智能体）可以读取和编辑工作区文件、运行命令、委派工作并维护计划。如果根据当前权限策略，某项操作需要审批，Web UI 会先询问你。</p><h2 id="查看会话概览" tabindex="-1">查看会话概览 <a class="header-anchor" href="#查看会话概览" aria-label="Permalink to &quot;查看会话概览&quot;">​</a></h2><p>会话打开后，Chat 视图右侧的信息卡按“协作”和“运行统计”分组，汇总当前会话的子代理、后台任务数量，以及轮次、步骤、LLM／工具耗时、首 token 延迟、生成速度和 token 用量；卡片不重复显示“会话概览”标题，输入框下方也不显示这些统计。统计来自整个会话；尚未产生样本的项目不会显示。页头原有的子代理和后台任务菜单仍可查看具体条目。Chat 页头右侧的列表形按钮在宽屏默认展开信息卡，侧栏占用空间或窗口变窄时默认收起；点击按钮可切换显示，展开的卡片也可从右上角收起。切换到轨迹等其他视图时，卡片与按钮隐藏，回到 Chat 后恢复先前的展开状态。</p><h2 id="继续使用" tabindex="-1">继续使用 <a class="header-anchor" href="#继续使用" aria-label="Permalink to &quot;继续使用&quot;">​</a></h2><ul><li><a href="./providers">配置模型</a></li><li><a href="./python-sdk">使用 Python SDK</a></li><li><a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/apps/cli/README.md" target="_blank" rel="noreferrer">使用其他 CLI 模式</a></li><li><a href="./../develop/basic/">开发插件</a></li></ul>',18)])])}const b=a(s,[["render",i]]);export{u as __pageData,b as default};
